// ====================================================================
// Nó 1: Validação de Entrada, Hash SHA-256 e Padronização de Binário
// ====================================================================
const crypto = require('crypto');
const incomingItem = $input.first();

if (!incomingItem.binary || Object.keys(incomingItem.binary).length === 0) {
  return [{
    json: {
      sucesso: false,
      erro: "Nenhum arquivo binário (PDF/Imagem) foi anexado na requisição.",
      codigo_erro: "ARQUIVO_AUSENTE",
      timestamp: new Date().toISOString()
    }
  }];
}

// Pega a primeira chave binária (ex: 'data', 'file', 'upload')
const binaryKeys = Object.keys(incomingItem.binary);
const mainBinaryKey = binaryKeys[0];
const binaryData = incomingItem.binary[mainBinaryKey];

// Gera Hash SHA-256 a partir do base64 para idempotência no n8n
const fileBuffer = Buffer.from(binaryData.data, 'base64');
const hashSha256 = crypto.createHash('sha256').update(fileBuffer).digest('hex');
const hashMd5 = crypto.createHash('md5').update(fileBuffer).digest('hex');

return [{
  json: {
    sucesso: true,
    metadados_arquivo: {
      nome_original: binaryData.fileName || 'nota_fiscal.pdf',
      mime_type: binaryData.mimeType || 'application/pdf',
      tamanho_bytes: fileBuffer.length,
      hash_sha256: hashSha256,
      hash_md5: hashMd5,
      recebido_em: new Date().toISOString()
    }
  },
  binary: {
    data: binaryData
  }
}];

// ====================================================================
// Nó 3: Sanitização, Auditoria de Consistência Matemática e Governança
// ====================================================================
const item = $input.first();
const metadados = item.json.metadados_arquivo || {};
let rawText = null;

// 1. Localiza a resposta de texto vinda do modelo LLM
JSON.stringify(item.json, (key, value) => {
  if ((key === 'text' || key === 'content') && typeof value === 'string') {
    rawText = value;
  }
  return value;
});

if (!rawText && item.json.message && item.json.message.content) {
  rawText = item.json.message.content;
}

if (!rawText) {
  return [{
    json: {
      sucesso: false,
      status: "ERRO_EXTRACAO",
      motivo: "Modelo de IA não retornou conteúdo textual analisável.",
      metadados: metadados
    }
  }];
}

// 2. Limpeza de Markdown (```json ... ```)
let cleanedText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
let dadosExtraidos = {};

try {
  dadosExtraidos = JSON.parse(cleanedText);
} catch (e) {
  return [{
    json: {
      sucesso: false,
      status: "ERRO_PARSER_JSON",
      motivo: "IA retornou estrutura inválida incompatível com JSON.",
      resposta_crua: rawText,
      metadados: metadados
    }
  }];
}

// 3. Auditoria de Consistência Matemática
const valores = dadosExtraidos.tributos_e_valores || {};
const bruto = Number(valores.valor_bruto) || 0;
const retencoes = Number(valores.total_retencoes) || 0;
const liquido = Number(valores.valor_liquido) || 0;

const liquidoCalculado = Number((bruto - retencoes).toFixed(2));
const diferencaMatematica = Number(Math.abs(liquidoCalculado - liquido).toFixed(2));
const matematicaConsistente = diferencaMatematica <= 0.05;

// 4. Mapeamento de Vertical da Holding pelo Tomador
let verticalIdentificada = dadosExtraidos.tomador?.vertical_holding || null;
const cnpjTomador = (dadosExtraidos.tomador?.cnpj || '').replace(/\D/g, '');

if (cnpjTomador.includes('19456789')) {
  verticalIdentificada = "Impact Hub Florianópolis";
} else if (cnpjTomador.includes('28345678')) {
  verticalIdentificada = "Salto Inclusão Produtiva";
} else if (cnpjTomador.includes('33987654')) {
  verticalIdentificada = "Impacta Mais Eventos";
} else if (!verticalIdentificada) {
  verticalIdentificada = "Companhia de Impacto (Geral)";
}

// 5. Checklist de Validação para Aprovação no Fluxo
const pendencias = [];
if (!dadosExtraidos.dados_documento?.numero_nf) pendencias.push("Número da NF ausente ou ilegível");
if (!dadosExtraidos.dados_documento?.data_vencimento) pendencias.push("Data de vencimento ausente ou não informada");
if (!dadosExtraidos.prestador?.cnpj_cpf) pendencias.push("CNPJ/CPF do prestador não identificado");
if (liquido <= 0) pendencias.push("Valor líquido da nota fiscal inválido ou zerado");
if (!matematicaConsistente) pendencias.push(`Divergência matemática: Bruto (${bruto}) - Retenções (${retencoes}) diverge do Líquido informado (${liquido}) em R$ ${diferencaMatematica}`);

const aprovadoParaFluxo = pendencias.length === 0;
const statusFinal = aprovadoParaFluxo ? "AGUARDANDO_APROVACAO" : "REVISAO_MANUAL";

// 6. Payload Final Consolidado
return [{
  json: {
    sucesso: true,
    status_operacional: statusFinal,
    idempotencia: {
      hash_sha256: metadados.hash_sha256,
      chave_duplicidade: `${dadosExtraidos.prestador?.cnpj_cpf || 'SEM_CNPJ'}_NF_${dadosExtraidos.dados_documento?.numero_nf || 'SEM_NUMERO'}`
    },
    dados_nota: {
      ...dadosExtraidos,
      tomador: {
        ...dadosExtraidos.tomador,
        vertical_holding_normalizada: verticalIdentificada
      }
    },
    auditoria: {
      matematica_consistente: matematicaConsistente,
      diferenca_apurada: diferencaMatematica,
      score_confianca: dadosExtraidos.confidence_score || 0.95,
      aprovado_automaticamente: aprovadoParaFluxo,
      pendencias_identificadas: pendencias
    },
    metadados_processamento: {
      arquivo_origem: metadados.nome_original,
      processado_em: new Date().toISOString(),
      versao_pipeline: "1.0.0-ImpactPay"
    }
  }
}];

// Rota de Sucesso: Dados íntegros prontos para persistência no banco e notificação do gestor
const item = $input.first().json;
return [{
  json: {
    ...item,
    proxima_acao: "DISPARAR_NOTIFICACAO_GESTOR",
    mensagem_sistema: "Nota Fiscal validada com sucesso com 100% de consistência tributária."
  }
}];

// Rota de Exceção: Falha na extração ou divergência matemática detectada
const item = $input.first().json;
return [{
  json: {
    ...item,
    proxima_acao: "ENCAMINHAR_FILA_EXCECOES_FINANCEIRO",
    mensagem_sistema: "Nota Fiscal retida para revisão manual da equipe financeira."
  }
}];
